const request = require('request');

const options = {
  method: 'GET',
  url: 'https://api.procore.com/rest/v1.0/companies/%7Bcompany_id%7D/capital_planning/change_history',
  qs: {
    search: 'SOME_STRING_VALUE',
    date_to: 'SOME_STRING_VALUE',
    date_from: 'SOME_STRING_VALUE',
    'changed[]': 'SOME_ARRAY_VALUE',
    'actor_id[]': 'SOME_ARRAY_VALUE',
    'project_id[]': 'SOME_ARRAY_VALUE',
    sort: 'SOME_STRING_VALUE',
    per_page: 'SOME_NUMBER_VALUE',
    page: 'SOME_NUMBER_VALUE'
  },
  headers: {'Procore-Company-Id': 'SOME_STRING_VALUE'}
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Get,
    RequestUri = new Uri("https://api.procore.com/rest/v1.0/companies/%7Bcompany_id%7D/capital_planning/change_history?search=SOME_STRING_VALUE&date_to=SOME_STRING_VALUE&date_from=SOME_STRING_VALUE&changed%5B%5D=SOME_ARRAY_VALUE&actor_id%5B%5D=SOME_ARRAY_VALUE&project_id%5B%5D=SOME_ARRAY_VALUE&sort=SOME_STRING_VALUE&per_page=SOME_NUMBER_VALUE&page=SOME_NUMBER_VALUE"),
    Headers =
    {
        { "Procore-Company-Id", "SOME_STRING_VALUE" },
    },
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}

